const brands = [
  { id: 'dax-collective', name: 'The Dax Collective', youtube: '@TheDaxCollective', tiktok: '@thedaxcollective', instagram: '@thedaxcollective', facebookPage: '/TheDaxCollective' },
  { id: 'dax-the-traveler', name: 'Dax the Traveler', youtube: '@DaxTheTraveler', tiktok: '@daxthetraveler', instagram: '@daxthetraveler', facebookPage: '/DaxTheTraveler' },
  { id: 'time-zone-travelers', name: 'Time-Zone Travelers', youtube: '@TimeZoneTravelers', tiktok: '@timezonetravelers', instagram: '@timezonetravelers', facebookPage: '/TimeZoneTravelers' },
  { id: 'ani-dax', name: 'Ani-Dax', youtube: '@AniDax', tiktok: '@anidax', instagram: '@anidax', facebookPage: '/AniDax' },
  { id: 'gods-vessel', name: "God's Vessel", youtube: '@GodsVessel', tiktok: '@godsvessel', instagram: '@godsvessel', facebookPage: '/GodsVessel' }
];

return brands.map((brand) => ({
  json: {
    brand: brand.id,
    brandName: brand.name,
    desiredHandles: brand,
    requiredPlatformSetup: {
      youtube: {
        required: true,
        status: 'blocked_until_google_oauth_and_channel_exists',
        userAction: 'Create or claim YouTube channel/Brand Account, then connect Google OAuth in n8n.'
      },
      facebookPage: {
        required: true,
        status: 'blocked_until_page_exists',
        userAction: 'Create Facebook Page under your existing Facebook account; do not create a new Facebook user account.'
      },
      instagram: {
        required: true,
        status: 'blocked_until_professional_account_linked_to_facebook_page',
        userAction: 'Create Instagram account, convert to Business/Creator, link it to the matching Facebook Page.'
      },
      tiktok: {
        required: true,
        status: 'blocked_until_tiktok_account_and_developer_app_ready',
        userAction: 'Create TikTok account, then create TikTok Developer app and request posting scopes if API publishing is needed.'
      }
    },
    requiredCompanySetup: {
      publicN8nUrl: 'required_for_oauth_callbacks',
      privacyPolicyUrl: 'required_for_google_meta_tiktok_apps',
      termsUrl: 'required_for_google_meta_tiktok_apps',
      n8nCredentials: 'store OAuth/client secrets only in n8n credentials UI, not workflow JSON'
    },
    publishAllowed: false,
    reviewStatus: 'setup_blocked',
    createdAt: new Date().toISOString()
  }
}));
